inputs = ['jgz', 'gbi', 'ah', 'zi', 'dz']
outputs = ['juwcu', 'gebi', 'ah', 'zi', 'dz']

# Let me be more systematic about identifying the minimal edits
print("Analyzing each transformation:")

for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"Example {i}: '{inp}' -> '{outp}'")
        # Find where they differ
        min_len = min(len(inp), len(outp))
        diff_pos = None
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break
        if diff_pos is None:
            if len(inp) != len(outp):
                diff_pos = min_len
        print(f"  First difference at position: {diff_pos}")

        # Try to figure out what was replaced
        if len(inp) < len(outp):
            # Insertion case
            print(f"  Appears to be insertion of characters")
        elif len(inp) > len(outp):
            # Deletion case  
            print(f"  Appears to be deletion of characters")
        else:
            # Substitution case
            print(f"  Appears to be substitution")
        print()

